import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    // Auth check
    const authHeader = req.headers.get("Authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabaseUser = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, {
      global: { headers: { Authorization: authHeader } },
    });

    const { data: userData, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !userData?.user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Admin check
    const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);
    const { data: roleData } = await supabaseAdmin
      .from("user_roles")
      .select("role")
      .eq("user_id", userData.user.id)
      .eq("role", "admin")
      .maybeSingle();

    if (!roleData) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    if (!DODO_API_KEY) {
      return new Response(JSON.stringify({ error: "DODO_PAYMENTS_API_KEY not configured" }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Determine environment
    const env = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    const baseUrl = env === "live_mode"
      ? "https://live.dodopayments.com"
      : "https://test.dodopayments.com";

    const body = await req.json();
    const { action, type, name, price, credits, billing_type, product_id } = body;

    if (!action || !["create", "update", "deactivate", "reactivate"].includes(action)) {
      return new Response(JSON.stringify({ error: "Invalid action. Use: create, update, deactivate, reactivate" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Helper: ensure credit entitlement exists ───
    const ensureCreditEntitlement = async (): Promise<string | null> => {
      // Check platform_config for stored credit entitlement ID
      const { data: config } = await supabaseAdmin
        .from("platform_config")
        .select("*")
        .limit(1)
        .single();

      const existingId = (config as any)?.dodo_credit_entitlement_id;
      if (existingId) return existingId;

      // Create a new credit entitlement on Dodo
      console.log("Creating Dodo credit entitlement for resume credits...");
      const resp = await fetch(`${baseUrl}/credit-entitlements`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify({
          name: "Resume Credits",
          unit: "credits",
          precision: 0,
          rollover_enabled: true,
          overage_enabled: false,
          description: "Credits used to rank resumes. 1 credit = 1 resume ranked.",
        }),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Failed to create credit entitlement:", resp.status, respBody);
        return null;
      }

      const entitlement = JSON.parse(respBody);
      const entitlementId = entitlement.id;

      // Store in platform_config for future use
      await supabaseAdmin
        .from("platform_config")
        .update({ dodo_credit_entitlement_id: entitlementId } as any)
        .eq("id", config?.id);

      console.log("Credit entitlement created:", entitlementId);
      return entitlementId;
    };

    let result: any = {};

    // ─── CREATE ───
    if (action === "create") {
      const priceObj: any = {
        currency: "USD",
        discount: 0,
        purchasing_power_parity: false,
      };

      if (type === "plan") {
        priceObj.type = "recurring_price";
        priceObj.payment_frequency_count = 1;
        priceObj.payment_frequency_interval = billing_type === "yearly" ? "Year" : "Month";
        priceObj.subscription_period_count = 1;
        priceObj.subscription_period_interval = billing_type === "yearly" ? "Year" : "Month";
        priceObj.trial_period_days = 0;
        priceObj.price = Math.round(price * 100);
      } else {
        priceObj.type = "one_time_price";
        priceObj.price = Math.round(price * 100);
      }

      const createPayload: any = {
        name,
        tax_category: "saas",
        price: priceObj,
      };

      // Attach credit entitlement if credits amount is provided
      if (credits && credits > 0) {
        const creditEntitlementId = await ensureCreditEntitlement();
        if (creditEntitlementId) {
          createPayload.credit_entitlements = [
            {
              credit_entitlement_id: creditEntitlementId,
              credits_amount: String(credits),
            },
          ];
        }
      }

      console.log("Creating Dodo product:", JSON.stringify(createPayload));

      const resp = await fetch(`${baseUrl}/products`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify(createPayload),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo create failed:", resp.status, respBody);
        return new Response(
          JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: respBody }),
          { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      result = JSON.parse(respBody);
      console.log("Dodo product created:", result.product_id);

    // ─── UPDATE ───
    } else if (action === "update") {
      if (!product_id) {
        return new Response(JSON.stringify({ error: "product_id required for update" }), {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const patchPayload: any = {};
      if (name) patchPayload.name = name;
      if (price !== undefined && price !== null) {
        const priceObj: any = {
          currency: "USD",
          discount: 0,
          purchasing_power_parity: false,
        };
        if (type === "plan") {
          priceObj.type = "recurring_price";
          priceObj.payment_frequency_count = 1;
          priceObj.payment_frequency_interval = billing_type === "yearly" ? "Year" : "Month";
          priceObj.subscription_period_count = 1;
          priceObj.subscription_period_interval = billing_type === "yearly" ? "Year" : "Month";
          priceObj.trial_period_days = 0;
          priceObj.price = Math.round(price * 100);
        } else {
          priceObj.type = "one_time_price";
          priceObj.price = Math.round(price * 100);
        }
        patchPayload.price = priceObj;
      }

      // Update credit entitlements if credits changed
      if (credits !== undefined && credits !== null && credits > 0) {
        const creditEntitlementId = await ensureCreditEntitlement();
        if (creditEntitlementId) {
          patchPayload.credit_entitlements = [
            {
              credit_entitlement_id: creditEntitlementId,
              credits_amount: String(credits),
            },
          ];
        }
      }

      console.log("Updating Dodo product:", product_id, JSON.stringify(patchPayload));

      const resp = await fetch(`${baseUrl}/products/${product_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify(patchPayload),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo update failed:", resp.status, respBody);
        return new Response(
          JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: respBody }),
          { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      result = { updated: true, product_id };

    // ─── DEACTIVATE (archive) ───
    } else if (action === "deactivate") {
      if (!product_id) {
        return new Response(JSON.stringify({ success: true, skipped: true }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      console.log("Deactivating Dodo product:", product_id);

      const resp = await fetch(`${baseUrl}/products/${product_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify({
          name: `[ARCHIVED] ${name || "Product"}`,
        }),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo deactivate failed:", resp.status, respBody);
        // Don't block local operation if Dodo fails
      }

      result = { deactivated: true, product_id };

    // ─── REACTIVATE (restore from archive) ───
    } else if (action === "reactivate") {
      if (!product_id) {
        return new Response(JSON.stringify({ success: true, skipped: true }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      console.log("Reactivating Dodo product:", product_id);

      const patchPayload: any = {};
      if (name) {
        patchPayload.name = name.replace(/^\[ARCHIVED\]\s*/, "");
      }

      const resp = await fetch(`${baseUrl}/products/${product_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify(patchPayload),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
