     1→import { useState } from "react";
     2→import { useQuery, useQueryClient } from "@tanstack/react-query";
     3→import { supabase } from "@/integrations/supabase/client";
     4→import { Button } from "@/components/ui/button";
     5→import { Input } from "@/components/ui/input";
     6→import { Label } from "@/components/ui/label";
     7→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     8→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
     9→import { Switch } from "@/components/ui/switch";
    10→import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
    11→import { Badge } from "@/components/ui/badge";
    12→import { toast } from "sonner";
    13→import { Plus, Pencil, Save, Trash2, Loader2, Gift, CheckCircle, AlertTriangle, Archive, RotateCcw } from "lucide-react";
    14→import ConfirmDialog from "./ConfirmDialog";
    15→import { logAuditAction } from "@/lib/auditLog";
    16→
    17→const syncDodoProduct = async (action: "create" | "update" | "deactivate" | "reactivate", payload: any) => {
    18→  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
    19→    body: { action, type: "credit_pack", ...payload },
    20→  });
    21→  if (error) throw error;
    22→  if (data?.error) throw new Error(data.error);
    23→  return data;
    24→};
    25→
    26→const CreditPacksTab = () => {
    27→  const qc = useQueryClient();
    28→  const [saving, setSaving] = useState(false);
    29→  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string } | null>(null);
    30→  const [showArchived, setShowArchived] = useState(false);
    31→
    32→  const { data: packs } = useQuery({
    33→    queryKey: ["admin_credit_packs"],
    34→    queryFn: async () => {
    35→      const { data, error } = await supabase.from("credit_packs").select("*").order("created_at");
    36→      if (error) throw error;
    37→      return data;
    38→    },
    39→  });
    40→
    41→  const activePacks = packs?.filter((p: any) => p.active) ?? [];
    42→  const archivedPacks = packs?.filter((p: any) => !p.active) ?? [];
    43→
    44→  const [editPack, setEditPack] = useState<any>(null);
    45→  const [form, setForm] = useState({ name: "", price: "", credits: "", active: true, is_trial: false });
    46→
    47→  const openNew = () => { setForm({ name: "", price: "", credits: "", active: true, is_trial: false }); setEditPack("new"); };
    48→  const openEdit = (p: any) => { setForm({ name: p.name, price: String(p.price), credits: String(p.credits), active: p.active, is_trial: p.is_trial ?? false }); setEditPack(p); };
    49→
    50→  const validate = () => {
    51→    if (!form.name.trim()) { toast.error("Pack name is required"); return false; }
    52→    if (!form.price || parseFloat(form.price) < 0) { toast.error("Price must be 0 or greater"); return false; }
    53→    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
    54→    if (form.is_trial && form.active) {
    55→      const existingTrial = packs?.find((p: any) => p.is_trial && p.active && (editPack === "new" || p.id !== editPack?.id));
    56→      if (existingTrial) { toast.error("Only one active trial pack is allowed. Deactivate the existing one first."); return false; }
    57→    }
    58→    return true;
    59→  };
    60→
    61→  const save = async () => {
    62→    if (!validate()) return;
    63→    setSaving(true);
    64→    try {
    65→      const payload = { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits), active: form.active, is_trial: form.is_trial } as any;
    66→
    67→      if (editPack === "new") {
    68→        const { data: inserted, error } = await supabase.from("credit_packs").insert(payload).select().single();
    69→        if (error) { toast.error(error.message); return; }
    70→
    71→        try {
    72→          const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
    73→          const dodoProductId = dodoResult.product_id;
    74→          if (dodoProductId) {
    75→            await supabase.from("credit_packs").update({ dodo_product_id: dodoProductId }).eq("id", inserted.id);
    76→            toast.success("Credit pack saved & synced with Dodo ✓");
    77→          } else {
    78→            toast.success("Credit pack saved (Dodo sync returned no product ID)");
    79→          }
    80→        } catch (dodoErr: any) {
    81→          console.error("Dodo sync failed:", dodoErr);
    82→          toast.warning("Pack saved locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
    83→        }
    84→      } else {
    85→        const { error } = await supabase.from("credit_packs").update(payload).eq("id", editPack.id);
    86→        if (error) { toast.error(error.message); return; }
    87→
    88→        if (editPack.dodo_product_id) {
    89→          try {
    90→            await syncDodoProduct("update", { product_id: editPack.dodo_product_id, name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
    91→            toast.success("Pack updated & synced with Dodo ✓");
    92→          } catch (dodoErr: any) {
    93→            console.error("Dodo sync failed:", dodoErr);
    94→            toast.warning("Pack updated locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
    95→          }
    96→        } else {
    97→          try {
    98→            const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
    99→            const dodoProductId = dodoResult.product_id;
   100→            if (dodoProductId) {
   101→              await supabase.from("credit_packs").update({ dodo_product_id: dodoProductId }).eq("id", editPack.id);
   102→              toast.success("Pack updated & linked to Dodo ✓");
   103→            } else {
   104→              toast.success("Pack updated");
   105→            }
   106→          } catch (dodoErr: any) {
   107→            console.error("Dodo create failed:", dodoErr);
   108→            toast.warning("Pack updated but Dodo link failed: " + (dodoErr.message || "Unknown error"));
   109→          }
   110→        }
   111→      }
   112→
   113→      logAuditAction(
   114→        editPack === "new" ? "credit_pack.create" : "credit_pack.update",
   115→        "credit_pack",
   116→        editPack === "new" ? undefined : editPack.id,
   117→        { name: form.name, price: form.price, credits: form.credits, is_trial: form.is_trial },
   118→      );
   119→      qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   120→      setEditPack(null);
   121→    } finally {
   122→      setSaving(false);
   123→    }
   124→  };
   125→
   126→  const handleArchive = async (pack: any) => {
   127→    if (pack.dodo_product_id) {
   128→      try { await syncDodoProduct("deactivate", { product_id: pack.dodo_product_id, name: pack.name }); } catch { /* continue */ }
   129→    }
   130→    const { error } = await supabase.from("credit_packs").update({ active: false }).eq("id", pack.id);
   131→    if (error) { toast.error(error.message); return; }
   132→    toast.success(`"${pack.name}" archived`);
   133→    logAuditAction("credit_pack.archive", "credit_pack", pack.id, { name: pack.name });
   134→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   135→  };
   136→
   137→  const handleRestore = async (pack: any) => {
   138→    // Reactivate on Dodo
   139→    if (pack.dodo_product_id) {
   140→      try { await syncDodoProduct("reactivate", { product_id: pack.dodo_product_id, name: pack.name, price: pack.price, credits: pack.credits }); } catch { /* continue */ }
   141→    }
   142→    const { error } = await supabase.from("credit_packs").update({ active: true }).eq("id", pack.id);
   143→    if (error) { toast.error(error.message); return; }
   144→    toast.success(`"${pack.name}" restored & synced with Dodo`);
   145→    logAuditAction("credit_pack.restore", "credit_pack", pack.id, { name: pack.name });
   146→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   147→  };
   148→
   149→  const confirmDelete = async () => {
   150→    if (!deleteTarget) return;
   151→
   152→    if (deleteTarget.dodo_product_id) {
   153→      try { await syncDodoProduct("deactivate", { product_id: deleteTarget.dodo_product_id }); } catch { /* continue */ }
   154→    }
   155→
   156→    const { error } = await supabase.from("credit_packs").delete().eq("id", deleteTarget.id);
   157→    if (error) {
   158→      const message = (error as any)?.message ?? "";
   159→      const code = (error as any)?.code;
   160→      if (code === "23503" || /foreign key/i.test(message)) {
   161→        toast.error("Cannot delete — this pack has existing payments. It will remain in the archive.");
   162→      } else {
   163→        toast.error(message || "Failed to delete");
   164→      }
   165→      setDeleteTarget(null);
   166→      return;
   167→    }
   168→    toast.success("Credit pack permanently deleted");
   169→    logAuditAction("credit_pack.delete", "credit_pack", deleteTarget.id, { name: deleteTarget.name });
   170→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   171→    setDeleteTarget(null);
   172→  };
   173→
   174→  const PackRow = ({ p, archived = false }: { p: any; archived?: boolean }) => (
   175→    <TableRow key={p.id} className={archived ? "opacity-60" : ""}>
   176→      <TableCell className="font-medium">
   177→        <div className="flex items-center gap-2">
   178→          {p.name}
   179→          {archived && <Badge variant="outline" className="text-[10px] text-muted-foreground">Archived</Badge>}
   180→        </div>
   181→      </TableCell>
   182→      <TableCell>${p.price}</TableCell>
   183→      <TableCell>{p.credits}</TableCell>
   184→      <TableCell>
   185→        {p.is_trial ? (
   186→          <Badge className="bg-gradient-to-r from-primary to-amber-500 text-primary-foreground border-0 text-[10px] gap-1">
   187→            <Gift className="h-3 w-3" /> Trial
   188→          </Badge>
   189→        ) : (
   190→          <span className="text-muted-foreground text-xs">Regular</span>
   191→        )}
   192→      </TableCell>
   193→      <TableCell>
   194→        {p.dodo_product_id ? (
   195→          <Badge variant="secondary" className="gap-1 text-[10px]">
   196→            <CheckCircle className="h-3 w-3 text-green-600" /> Linked
   197→          </Badge>
   198→        ) : (
   199→          <Badge variant="outline" className="gap-1 text-[10px] text-muted-foreground">
   200→            <AlertTriangle className="h-3 w-3 text-amber-500" /> Not linked
   201→          </Badge>
   202→        )}
   203→      </TableCell>
   204→      <TableCell className="flex gap-1">
   205→        {archived ? (
   206→          <>
   207→            <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
   208→              <RotateCcw className="h-3.5 w-3.5 text-primary" />
   209→            </Button>
   210→            <Button variant="ghost" size="icon" title="Delete permanently" onClick={() => setDeleteTarget({ id: p.id, name: p.name, dodo_product_id: p.dodo_product_id })}>
   211→              <Trash2 className="h-3.5 w-3.5 text-destructive" />
   212→            </Button>
   213→          </>
   214→        ) : (
   215→          <>
   216→            <Button variant="ghost" size="icon" onClick={() => openEdit(p)}><Pencil className="h-3.5 w-3.5" /></Button>
   217→            <Button variant="ghost" size="icon" title="Archive" onClick={() => handleArchive(p)}>
   218→              <Archive className="h-3.5 w-3.5 text-muted-foreground" />
   219→            </Button>
   220→          </>
   221→        )}
   222→      </TableCell>
   223→    </TableRow>
   224→  );
   225→
   226→  return (
   227→    <>
   228→      <Card>
   229→        <CardHeader className="flex flex-row items-center justify-between pb-3">
   230→          <CardTitle className="text-lg">Credit Packs</CardTitle>
   231→          <Dialog open={editPack !== null} onOpenChange={(o) => !o && setEditPack(null)}>
   232→            <DialogTrigger asChild>
   233→              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Pack</Button>
   234→            </DialogTrigger>
   235→            <DialogContent>
   236→              <DialogHeader><DialogTitle>{editPack === "new" ? "New Credit Pack" : "Edit Credit Pack"}</DialogTitle></DialogHeader>
   237→              <div className="space-y-3">
   238→                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Starter Pack" /></div>
   239→                <div className="grid grid-cols-2 gap-3">
   240→                  <div><Label>Price ($)</Label><Input type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
   241→                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
   242→                </div>
   243→                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
   244→                <div className="flex items-center gap-2">
   245→                  <Switch checked={form.is_trial} onCheckedChange={(c) => setForm({ ...form, is_trial: c })} />
   246→                  <Label className="flex items-center gap-1.5">
   247→                    <Gift className="h-3.5 w-3.5 text-amber-500" />
   248→                    Trial Pack
   249→                  </Label>
   250→                </div>
   251→                {form.is_trial && (
   252→                  <p className="text-xs text-muted-foreground bg-amber-500/10 rounded-md px-3 py-2">
   253→                    Trial packs are only visible to users who haven't made any purchase yet. Only one active trial pack is allowed.
   254→                  </p>
   255→                )}
   256→                <p className="text-xs text-muted-foreground bg-muted rounded-md px-3 py-2">
   257→                  Dodo product will be auto-created/synced when you save.
   258→                </p>
   259→                <Button onClick={save} className="w-full" disabled={saving}>
   260→                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
   261→                  {saving ? "Saving & Syncing..." : "Save"}
   262→                </Button>
   263→              </div>
