import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    // Auth check
    const authHeader = req.headers.get("Authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabaseUser = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, {
      global: { headers: { Authorization: authHeader } },
    });

    const { data: userData, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !userData?.user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Admin check
    const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);
    const { data: roleData } = await supabaseAdmin
      .from("user_roles")
      .select("role")
      .eq("user_id", userData.user.id)
      .eq("role", "admin")
      .maybeSingle();

    if (!roleData) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    if (!DODO_API_KEY) {
      return new Response(JSON.stringify({ error: "DODO_PAYMENTS_API_KEY not configured" }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Determine environment
    const env = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    const baseUrl = env === "live_mode"
      ? "https://live.dodopayments.com"
      : "https://test.dodopayments.com";

    const body = await req.json();
    const { action, type, name, price, credits, billing_type, product_id } = body;

    if (!action || !["create", "update", "deactivate", "reactivate"].includes(action)) {
      return new Response(JSON.stringify({ error: "Invalid action. Use: create, update, deactivate, reactivate" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Helper: create a per-product credit entitlement ───
    // Each product gets its own credit entitlement named "$15 - 300 Credits"
    const createCreditEntitlement = async (packPrice: number, packCredits: number): Promise<string | null> => {
      const entitlementName = `$${packPrice} - ${packCredits} Credits`;
      console.log(`Creating Dodo credit entitlement: "${entitlementName}"...`);

      const resp = await fetch(`${baseUrl}/credit-entitlements`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify({
          name: entitlementName,
          unit: "credits",
          precision: 0,
          rollover_enabled: false,
          overage_enabled: false,
          description: `${packCredits} credits included. 1 credit = 1 resume ranked.`,
        }),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Failed to create credit entitlement:", resp.status, respBody);
        return null;
      }

      const entitlement = JSON.parse(respBody);
      console.log("Credit entitlement created:", entitlement.id, entitlementName);
      return entitlement.id;
    };

    let result: any = {};

    // ─── CREATE ───
    if (action === "create") {
      const priceObj: any = {
        currency: "USD",
        discount: 0,
        purchasing_power_parity: false,
      };

      if (type === "plan") {
        priceObj.type = "recurring_price";
        priceObj.payment_frequency_count = 1;
        priceObj.payment_frequency_interval = billing_type === "yearly" ? "Year" : "Month";
        priceObj.subscription_period_count = 1;
        priceObj.subscription_period_interval = billing_type === "yearly" ? "Year" : "Month";
        priceObj.trial_period_days = 0;
        priceObj.price = Math.round(price * 100);
      } else {
        priceObj.type = "one_time_price";
        priceObj.price = Math.round(price * 100);
      }

      const createPayload: any = {
        name,
        tax_category: "saas",
        price: priceObj,
      };

      // Attach credit entitlement if credits amount is provided
      if (credits && credits > 0) {
        const creditEntitlementId = await createCreditEntitlement(price, credits);
        if (creditEntitlementId) {
          createPayload.credit_entitlements = [
            {
              credit_entitlement_id: creditEntitlementId,
              credits_amount: String(credits),
            },
          ];
        }
      }

      console.log("Creating Dodo product:", JSON.stringify(createPayload));

      const resp = await fetch(`${baseUrl}/products`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify(createPayload),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo create failed:", resp.status, respBody);
        return new Response(
          JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: respBody }),
          { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      result = JSON.parse(respBody);
      console.log("Dodo product created:", result.product_id);

    // ─── UPDATE ───
    } else if (action === "update") {
      if (!product_id) {
        return new Response(JSON.stringify({ error: "product_id required for update" }), {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const patchPayload: any = {};
      if (name) patchPayload.name = name;
      if (price !== undefined && price !== null) {
        const priceObj: any = {
          currency: "USD",
          discount: 0,
          purchasing_power_parity: false,
        };
        if (type === "plan") {
          priceObj.type = "recurring_price";
          priceObj.payment_frequency_count = 1;
          priceObj.payment_frequency_interval = billing_type === "yearly" ? "Year" : "Month";
          priceObj.subscription_period_count = 1;
          priceObj.subscription_period_interval = billing_type === "yearly" ? "Year" : "Month";
          priceObj.trial_period_days = 0;
          priceObj.price = Math.round(price * 100);
        } else {
          priceObj.type = "one_time_price";
          priceObj.price = Math.round(price * 100);
        }
        patchPayload.price = priceObj;
      }

      // Update credit entitlements if credits changed
      if (credits !== undefined && credits !== null && credits > 0) {
        const creditEntitlementId = await createCreditEntitlement(price ?? 0, credits);
        if (creditEntitlementId) {
          patchPayload.credit_entitlements = [
            {
              credit_entitlement_id: creditEntitlementId,
              credits_amount: String(credits),
            },
          ];
        }
      }

      console.log("Updating Dodo product:", product_id, JSON.stringify(patchPayload));

      const resp = await fetch(`${baseUrl}/products/${product_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify(patchPayload),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo update failed:", resp.status, respBody);
        return new Response(
          JSON.stringify({ error: `Dodo API error: ${resp.status}`, details: respBody }),
          { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      result = { updated: true, product_id };

    // ─── DEACTIVATE (archive) ───
    } else if (action === "deactivate") {
      if (!product_id) {
        return new Response(JSON.stringify({ success: true, skipped: true }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      console.log("Deactivating Dodo product:", product_id);

      const resp = await fetch(`${baseUrl}/products/${product_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify({
          name: `[ARCHIVED] ${name || "Product"}`,
        }),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo deactivate failed:", resp.status, respBody);
        // Don't block local operation if Dodo fails
      }

      result = { deactivated: true, product_id };

    // ─── REACTIVATE (restore from archive) ───
    } else if (action === "reactivate") {
      if (!product_id) {
        return new Response(JSON.stringify({ success: true, skipped: true }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      console.log("Reactivating Dodo product:", product_id);

      const patchPayload: any = {};
      if (name) {
        patchPayload.name = name.replace(/^\[ARCHIVED\]\s*/, "");
      }

      const resp = await fetch(`${baseUrl}/products/${product_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${DODO_API_KEY}`,
        },
        body: JSON.stringify(patchPayload),
      });

      const respBody = await resp.text();
      if (!resp.ok) {
        console.error("Dodo reactivate failed:", resp.status, respBody);
      }

      result = { reactivated: true, product_id };
    }

    return new Response(JSON.stringify({ success: true, ...result }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    console.error("manage-dodo-product error:", err);
    return new Response(JSON.stringify({ error: err.message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Plus, Pencil, Save, Trash2, Loader2, Gift, CheckCircle, AlertTriangle, Archive, RotateCcw } from "lucide-react";
import ConfirmDialog from "./ConfirmDialog";
import { logAuditAction } from "@/lib/auditLog";

const syncDodoProduct = async (action: "create" | "update" | "deactivate" | "reactivate", payload: any) => {
  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
    body: { action, type: "credit_pack", ...payload },
  });
  if (error) throw error;
  if (data?.error) throw new Error(data.error);
  return data;
};

const CreditPacksTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string } | null>(null);
  const [showArchived, setShowArchived] = useState(false);

  const { data: packs } = useQuery({
    queryKey: ["admin_credit_packs"],
    queryFn: async () => {
      const { data, error } = await supabase.from("credit_packs").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const activePacks = packs?.filter((p: any) => p.active) ?? [];
  const archivedPacks = packs?.filter((p: any) => !p.active) ?? [];

  const [editPack, setEditPack] = useState<any>(null);
  const [form, setForm] = useState({ name: "", price: "", credits: "", active: true, is_trial: false });

  const openNew = () => { setForm({ name: "", price: "", credits: "", active: true, is_trial: false }); setEditPack("new"); };
  const openEdit = (p: any) => { setForm({ name: p.name, price: String(p.price), credits: String(p.credits), active: p.active, is_trial: p.is_trial ?? false }); setEditPack(p); };

  const validate = () => {
    if (!form.name.trim()) { toast.error("Pack name is required"); return false; }
    if (!form.price || parseFloat(form.price) < 0) { toast.error("Price must be 0 or greater"); return false; }
    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
    if (form.is_trial && form.active) {
      const existingTrial = packs?.find((p: any) => p.is_trial && p.active && (editPack === "new" || p.id !== editPack?.id));
      if (existingTrial) { toast.error("Only one active trial pack is allowed. Deactivate the existing one first."); return false; }
    }
    return true;
  };

  const save = async () => {
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits), active: form.active, is_trial: form.is_trial } as any;

      if (editPack === "new") {
        const { data: inserted, error } = await supabase.from("credit_packs").insert(payload).select().single();
        if (error) { toast.error(error.message); return; }

        try {
          const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
          const dodoProductId = dodoResult.product_id;
          if (dodoProductId) {
            await supabase.from("credit_packs").update({ dodo_product_id: dodoProductId }).eq("id", inserted.id);
            toast.success("Credit pack saved & synced with Dodo ✓");
          } else {
            toast.success("Credit pack saved (Dodo sync returned no product ID)");
          }
        } catch (dodoErr: any) {
          console.error("Dodo sync failed:", dodoErr);
          toast.warning("Pack saved locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
        }
      } else {
        const { error } = await supabase.from("credit_packs").update(payload).eq("id", editPack.id);
        if (error) { toast.error(error.message); return; }

        if (editPack.dodo_product_id) {
          try {
            await syncDodoProduct("update", { product_id: editPack.dodo_product_id, name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
            toast.success("Pack updated & synced with Dodo ✓");
          } catch (dodoErr: any) {
            console.error("Dodo sync failed:", dodoErr);
            toast.warning("Pack updated locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
          }
        } else {
          try {
            const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
            const dodoProductId = dodoResult.product_id;
            if (dodoProductId) {
              await supabase.from("credit_packs").update({ dodo_product_id: dodoProductId }).eq("id", editPack.id);
              toast.success("Pack updated & linked to Dodo ✓");
            } else {
              toast.success("Pack updated");
            }
          } catch (dodoErr: any) {
            console.error("Dodo create failed:", dodoErr);
            toast.warning("Pack updated but Dodo link failed: " + (dodoErr.message || "Unknown error"));
          }
        }
      }

      logAuditAction(
        editPack === "new" ? "credit_pack.create" : "credit_pack.update",
        "credit_pack",
        editPack === "new" ? undefined : editPack.id,
        { name: form.name, price: form.price, credits: form.credits, is_trial: form.is_trial },
      );
      qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
      setEditPack(null);
    } finally {
      setSaving(false);
    }
  };

  const handleArchive = async (pack: any) => {
    if (pack.dodo_product_id) {
      try { await syncDodoProduct("deactivate", { product_id: pack.dodo_product_id, name: pack.name }); } catch { /* continue */ }
    }
    const { error } = await supabase.from("credit_packs").update({ active: false }).eq("id", pack.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`"${pack.name}" archived`);
    logAuditAction("credit_pack.archive", "credit_pack", pack.id, { name: pack.name });
    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
  };

  const handleRestore = async (pack: any) => {
    // Reactivate on Dodo
    if (pack.dodo_product_id) {
      try { await syncDodoProduct("reactivate", { product_id: pack.dodo_product_id, name: pack.name, price: pack.price, credits: pack.credits }); } catch { /* continue */ }
    }
    const { error } = await supabase.from("credit_packs").update({ active: true }).eq("id", pack.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`"${pack.name}" restored & synced with Dodo`);
    logAuditAction("credit_pack.restore", "credit_pack", pack.id, { name: pack.name });
    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;

    if (deleteTarget.dodo_product_id) {
      try { await syncDodoProduct("deactivate", { product_id: deleteTarget.dodo_product_id }); } catch { /* continue */ }
    }

    const { error } = await supabase.from("credit_packs").delete().eq("id", deleteTarget.id);
    if (error) {
      const message = (error as any)?.message ?? "";
      const code = (error as any)?.code;
      if (code === "23503" || /foreign key/i.test(message)) {
        toast.error("Cannot delete — this pack has existing payments. It will remain in the archive.");
      } else {
        toast.error(message || "Failed to delete");
      }
      setDeleteTarget(null);
      return;
    }
    toast.success("Credit pack permanently deleted");
    logAuditAction("credit_pack.delete", "credit_pack", deleteTarget.id, { name: deleteTarget.name });
    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
    setDeleteTarget(null);
  };

  const PackRow = ({ p, archived = false }: { p: any; archived?: boolean }) => (
    <TableRow key={p.id} className={archived ? "opacity-60" : ""}>
      <TableCell className="font-medium">
        <div className="flex items-center gap-2">
          {p.name}
          {archived && <Badge variant="outline" className="text-[10px] text-muted-foreground">Archived</Badge>}
        </div>
      </TableCell>
      <TableCell>${p.price}</TableCell>
      <TableCell>{p.credits}</TableCell>
      <TableCell>
        {p.is_trial ? (
          <Badge className="bg-gradient-to-r from-primary to-amber-500 text-primary-foreground border-0 text-[10px] gap-1">
            <Gift className="h-3 w-3" /> Trial
