        ) : (
          <span className="text-muted-foreground text-xs">Regular</span>
        )}
      </TableCell>
      <TableCell>
        {p.dodo_product_id ? (
          <Badge variant="secondary" className="gap-1 text-[10px]">
            <CheckCircle className="h-3 w-3 text-green-600" /> Linked
          </Badge>
        ) : (
          <Badge variant="outline" className="gap-1 text-[10px] text-muted-foreground">
            <AlertTriangle className="h-3 w-3 text-amber-500" /> Not linked
          </Badge>
        )}
      </TableCell>
      <TableCell className="flex gap-1">
        {archived ? (
          <>
            <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
