import { Plus, Pencil, Save, Trash2, Loader2, Gift, CheckCircle, AlertTriangle, Archive, RotateCcw } from "lucide-react";
import ConfirmDialog from "./ConfirmDialog";
import { logAuditAction } from "@/lib/auditLog";

const syncDodoProduct = async (action: "create" | "update" | "deactivate" | "reactivate", payload: any) => {
  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
    body: { action, type: "credit_pack", ...payload },
  });
  if (error) throw error;
  if (data?.error) throw new Error(data.error);
  return data;
};

const CreditPacksTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string; dodo_credit_entitlement_id?: string } | null>(null);
