    queryFn: async () => {
      const { data, error } = await supabase.from("plans").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const activePlans = plans?.filter((p: any) => p.active) ?? [];
  const archivedPlans = plans?.filter((p: any) => !p.active) ?? [];

  const [editPlan, setEditPlan] = useState<any>(null);
  const [form, setForm] = useState({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05" });

  const openNew = () => {
    setForm({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05" });
