      </TableCell>
      <TableCell className="flex gap-1">
        {archived ? (
          <>
            <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
              <RotateCcw className="h-3.5 w-3.5 text-primary" />
            </Button>
            <Button variant="ghost" size="icon" title="Delete permanently" onClick={() => setDeleteTarget({ id: p.id, name: p.name, dodo_product_id: p.dodo_product_id })}>
              <Trash2 className="h-3.5 w-3.5 text-destructive" />
            </Button>
          </>
        ) : (
          <>
            <Button variant="ghost" size="icon" onClick={() => openEdit(p)}><Pencil className="h-3.5 w-3.5" /></Button>
            <Button variant="ghost" size="icon" title="Archive" onClick={() => handleArchive(p)}>
              <Archive className="h-3.5 w-3.5 text-muted-foreground" />
            </Button>
          </>
        )}
      </TableCell>
    </TableRow>
  );

  return (
    <>
      <Card>
        <CardHeader className="flex flex-row items-center justify-between pb-3">
          <CardTitle className="text-lg">Subscription Plans</CardTitle>
          <Dialog open={editPlan !== null} onOpenChange={(o) => !o && setEditPlan(null)}>
            <DialogTrigger asChild>
              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Plan</Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>{editPlan === "new" ? "New Plan" : "Edit Plan"}</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Pro Monthly" /></div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Price ($)</Label><Input type="number" min="0.01" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Billing Type</Label><Input value={form.billing_type} onChange={(e) => setForm({ ...form, billing_type: e.target.value })} /></div>
                  <div><Label>Per Resume Cost ($)</Label><Input type="number" step="0.01" min="0" value={form.per_resume_cost} onChange={(e) => setForm({ ...form, per_resume_cost: e.target.value })} /></div>
                </div>
                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
                <p className="text-xs text-muted-foreground bg-muted rounded-md px-3 py-2">
                  Dodo product will be auto-created/synced when you save.
                </p>
                <Button onClick={save} className="w-full" disabled={saving}>
                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
                  {saving ? "Saving & Syncing..." : "Save"}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Price</TableHead>
                <TableHead>Credits</TableHead>
                <TableHead>$/Resume</TableHead>
                <TableHead>Billing</TableHead>
                <TableHead>Dodo</TableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {activePlans.length === 0 && archivedPlans.length === 0 && (
                <TableRow><TableCell colSpan={7} className="text-center text-muted-foreground py-8">No plans yet</TableCell></TableRow>
              )}
              {activePlans.map((p: any) => <PlanRow key={p.id} p={p} />)}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Archived section */}
      {archivedPlans.length > 0 && (
        <Card className="border-dashed">
          <CardHeader className="pb-3">
            <button
              onClick={() => setShowArchived(!showArchived)}
              className="flex items-center gap-2 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
            >
              <Archive className="h-4 w-4" />
              Archived Plans ({archivedPlans.length})
              <span className="text-xs">{showArchived ? "▾" : "▸"}</span>
            </button>
          </CardHeader>
          {showArchived && (
            <CardContent className="p-0">
              <Table>
                <TableBody>
                  {archivedPlans.map((p: any) => <PlanRow key={p.id} p={p} archived />)}
                </TableBody>
              </Table>
            </CardContent>
          )}
        </Card>
      )}

      <ConfirmDialog
        open={deleteTarget !== null}
        onOpenChange={(o) => !o && setDeleteTarget(null)}
        title="Permanently Delete Plan"
        description={`Are you sure you want to permanently delete "${deleteTarget?.name}"? If it has existing payments, this will fail and it will remain archived.`}
        confirmLabel="Delete Permanently"
        onConfirm={confirmDelete}
      />
    </>
  );
};

export default PlansTab;

