// ─── Postmark Card ───
const PostmarkCard = ({ integration, config, onTest, testing, onNavigateToEmail }: any) => {
  const [editing, setEditing] = useState(false);
  const [showToken, setShowToken] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    postmark_api_token: config?.postmark_api_token || "",
    email_from_address: config?.email_from_address || "noreply@rankora.co",
    email_from_name: config?.email_from_name || "Rankora",
    outbound_email_enabled: config?.outbound_email_enabled ?? false,
  });

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({
          postmark_api_token: form.postmark_api_token || null,
          email_from_address: form.email_from_address,
          email_from_name: form.email_from_name,
          outbound_email_enabled: form.outbound_email_enabled,
        } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Postmark settings saved");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "postmark" });
      setEditing(false);
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const maskedToken = form.postmark_api_token
    ? form.postmark_api_token.slice(0, 8) + "••••••••••••••••••••" + form.postmark_api_token.slice(-4)
    : "";

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
              <Mail className="h-5 w-5 text-primary" />
            </div>
            <div>
              <CardTitle className="text-base">Postmark</CardTitle>
              <p className="text-sm text-muted-foreground">Transactional email delivery</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <StatusBadge status={integration?.last_test_status} />
            <Button variant="ghost" size="sm" onClick={() => setEditing(!editing)}>
              <Settings className="h-3.5 w-3.5 mr-1" />{editing ? "Cancel" : "Edit"}
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {editing ? (
          <div className="space-y-3 rounded-md border p-4">
            <div>
              <Label className="text-xs">API Token</Label>
              <div className="flex gap-2 mt-1">
                <Input
                  type={showToken ? "text" : "password"}
                  value={form.postmark_api_token}
                  onChange={(e) => setForm({ ...form, postmark_api_token: e.target.value })}
                  placeholder="Enter Postmark server token"
                  className="font-mono text-sm"
                />
                <Button variant="ghost" size="icon" onClick={() => setShowToken(!showToken)}>
                  {showToken ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </Button>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs">From Address</Label>
                <Input
                  value={form.email_from_address}
                  onChange={(e) => setForm({ ...form, email_from_address: e.target.value })}
                  placeholder="noreply@rankora.co"
                  className="mt-1"
                />
              </div>
              <div>
                <Label className="text-xs">From Name</Label>
                <Input
                  value={form.email_from_name}
                  onChange={(e) => setForm({ ...form, email_from_name: e.target.value })}
                  placeholder="Rankora"
                  className="mt-1"
                />
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Switch
                checked={form.outbound_email_enabled}
                onCheckedChange={(c) => setForm({ ...form, outbound_email_enabled: c })}
              />
              <Label className="text-sm">Outbound email enabled</Label>
            </div>
            <Button size="sm" onClick={save} disabled={saving}>
              {saving ? <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" /> : <Save className="h-3.5 w-3.5 mr-1" />}
              Save Changes
            </Button>
          </div>
        ) : (
          <div className="rounded-md border bg-muted/40 p-3 space-y-2 text-sm">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">API Token</span>
              <span className="font-mono text-xs">{maskedToken || <span className="text-muted-foreground italic">Not configured</span>}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">From Address</span>
              <span>{config?.email_from_address || "noreply@rankora.co"}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">From Name</span>
              <span>{config?.email_from_name || "Rankora"}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">Outbound Email</span>
              <Badge variant={config?.outbound_email_enabled ? "default" : "secondary"} className="text-xs">
                {config?.outbound_email_enabled ? "Enabled" : "Disabled"}
              </Badge>
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="flex items-center justify-between pt-1 border-t">
          <p className="text-xs text-muted-foreground">
            {integration?.last_tested_at
              ? `Last tested: ${new Date(integration.last_tested_at).toLocaleString()}`
              : "Never tested"}
          </p>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => onTest("POSTMARK_API_TOKEN")} disabled={testing === "POSTMARK_API_TOKEN"}>
              {testing === "POSTMARK_API_TOKEN" ? <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" /> : null}
              Test Connection
            </Button>
            {onNavigateToEmail && (
              <Button variant="ghost" size="sm" onClick={onNavigateToEmail}>
                <Settings className="h-3.5 w-3.5 mr-1" />Email Settings
              </Button>
            )}
            <Button variant="ghost" size="sm" asChild>
              <a href="https://account.postmarkapp.com/servers" target="_blank" rel="noopener noreferrer">
                <ExternalLink className="h-3.5 w-3.5 mr-1" />Dashboard
              </a>
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

// ─── Dodo Payments Card ───
const DodoCard = ({ integration, config, onTest, testing }: any) => {
  const [showGuide, setShowGuide] = useState(false);
  const [environment, setEnvironment] = useState<string>(config?.dodo_payments_environment || "test_mode");
  const [saving, setSaving] = useState(false);

  const saveEnvironment = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({ dodo_payments_environment: environment } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Dodo environment updated");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "dodo", environment });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const envChanged = environment !== (config?.dodo_payments_environment || "test_mode");

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
              <CreditCard className="h-5 w-5 text-primary" />
            </div>
            <div>
              <CardTitle className="text-base">Dodo Payments</CardTitle>
              <p className="text-sm text-muted-foreground">Payment processing and subscriptions</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <StatusBadge status={integration?.last_test_status} />
            <Badge variant={environment === "live_mode" ? "default" : "secondary"} className="text-xs">
              {environment === "live_mode" ? "Live" : "Test"}
            </Badge>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Editable fields */}
        <div className="rounded-md border p-4 space-y-3">
          <div>
            <Label className="text-xs">Environment</Label>
            <div className="flex gap-2 mt-1">
              <Select value={environment} onValueChange={setEnvironment}>
                <SelectTrigger className="flex-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="test_mode">Test Mode (sandbox)</SelectItem>
                  <SelectItem value="live_mode">Live Mode (production)</SelectItem>
                </SelectContent>
              </Select>
              {envChanged && (
                <Button size="sm" onClick={saveEnvironment} disabled={saving}>
                  {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
                </Button>
              )}
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              Also set <code className="bg-muted px-1 rounded">DODO_PAYMENTS_ENVIRONMENT</code> in Supabase Edge Function Secrets to match
            </p>
          </div>
          <div className="bg-muted/40 rounded-md p-3 text-sm space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">API Key</span>
              <Badge variant="outline" className="text-xs">Env Secret: DODO_PAYMENTS_API_KEY</Badge>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">Webhook Secret</span>
              <Badge variant="outline" className="text-xs">Env Secret: DODO_PAYMENTS_WEBHOOK_SECRET</Badge>
            </div>
          </div>
        </div>

        {/* Setup guide toggle */}
        <button
          onClick={() => setShowGuide(!showGuide)}
          className="flex items-center gap-1.5 text-sm text-primary hover:underline"
        >
          {showGuide ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
          {showGuide ? "Hide" : "Show"} setup guide
        </button>
        {showGuide && <DodoGuide />}

        {/* Footer */}
        <div className="flex items-center justify-between pt-1 border-t">
          <p className="text-xs text-muted-foreground">
            {integration?.last_tested_at
              ? `Last tested: ${new Date(integration.last_tested_at).toLocaleString()}`
              : "Never tested"}
          </p>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => onTest("DODO_PAYMENTS_API_KEY")} disabled={testing === "DODO_PAYMENTS_API_KEY"}>
              {testing === "DODO_PAYMENTS_API_KEY" ? <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" /> : null}
              Test Connection
            </Button>
            <Button variant="ghost" size="sm" asChild>
              <a href="https://dashboard.dodopayments.com" target="_blank" rel="noopener noreferrer">
                <ExternalLink className="h-3.5 w-3.5 mr-1" />Dashboard
              </a>
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

// ─── Main Tab ───
const IntegrationsTab = ({ onNavigateToEmail }: { onNavigateToEmail?: () => void }) => {
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations } = useQuery({
    queryKey: ["admin_integrations"],
    queryFn: async () => {
      const { data, error } = await supabase.from("integrations").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const { data: config } = useQuery({
    queryKey: ["platform_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: keyName },
      });
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  const getIntegration = (key: string) => integrations?.find((i: any) => i.key_name === key);

  return (
    <div className="space-y-6">
      <h2 className="text-xl font-semibold">Integrations</h2>
      <div className="grid gap-6">
        <OpenAICard
          integration={getIntegration("OPENAI_API_KEY")}
          onTest={testIntegration}
          testing={testing}
        />
        <PostmarkCard
          integration={getIntegration("POSTMARK_API_TOKEN")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onNavigateToEmail={onNavigateToEmail}
        />
        <DodoCard
          integration={getIntegration("DODO_PAYMENTS_API_KEY")}
          config={config}
          onTest={testIntegration}
          testing={testing}
        />
      </div>
    </div>
  );
};

export default IntegrationsTab;

