import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Plug, CheckCircle2, XCircle, Loader2, ExternalLink, Mail, Brain, CreditCard } from "lucide-react";
import { useState } from "react";

const IntegrationsTab = () => {
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations } = useQuery({
    queryKey: ["admin_integrations"],
    queryFn: async () => {
      const { data, error } = await supabase.from("integrations").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: keyName },
      });
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-xl font-semibold">Integrations</h2>
      <div className="grid gap-4">
        {integrations?.map((integration: any) => {
          // Skip deprecated Razorpay integration if it still exists in DB
          if (integration.key_name === "RAZORPAY_KEY_ID") return null;

          const iconMap: Record<string, React.ElementType> = {
            OPENAI_API_KEY: Brain,
            POSTMARK_API_TOKEN: Mail,
            DODO_PAYMENTS_API_KEY: CreditCard,
          };
          const Icon = iconMap[integration.key_name] || Plug;
          const dashboardLinks: Record<string, string> = {
            OPENAI_API_KEY: "https://platform.openai.com/api-keys",
            POSTMARK_API_TOKEN: "https://account.postmarkapp.com/servers",
            DODO_PAYMENTS_API_KEY: "https://dashboard.dodopayments.com",
          };
          const dashboardLink = dashboardLinks[integration.key_name] ||
            "https://supabase.com/dashboard/project/zkzontawprihrzpayeam/settings/functions";

          return (
          <Card key={integration.id}>
            <CardHeader className="flex flex-row items-center justify-between pb-3">
              <div className="flex items-center gap-3">
                <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
                  <Icon className="h-5 w-5 text-primary" />
                </div>
                <div>
                  <CardTitle className="text-base">{integration.display_name}</CardTitle>
                  <p className="text-sm text-muted-foreground">{integration.description}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {integration.last_test_status === "success" ? (
                  <Badge variant="default" className="gap-1 bg-green-600"><CheckCircle2 className="h-3 w-3" />Connected</Badge>
                ) : integration.last_test_status === "failed" ? (
                  <Badge variant="destructive" className="gap-1"><XCircle className="h-3 w-3" />Failed</Badge>
                ) : (
                  <Badge variant="secondary">Not tested</Badge>
                )}
              </div>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <div className="text-sm text-muted-foreground">
                  {integration.last_tested_at
                    ? `Last tested: ${new Date(integration.last_tested_at).toLocaleString()}`
                    : "Never tested"}
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => testIntegration(integration.key_name)}
                    disabled={testing === integration.key_name}
                  >
                    {testing === integration.key_name ? (
                      <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" />
                    ) : null}
                    Test Connection
                  </Button>
                  <Button variant="ghost" size="sm" asChild>
                    <a
                      href={dashboardLink}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <ExternalLink className="h-3.5 w-3.5 mr-1" />
                      Manage
                    </a>
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
          );
        })}
      </div>
    </div>
  );
};

export default IntegrationsTab;

