const IntegrationsTab = ({ onNavigateToEmail }: { onNavigateToEmail?: () => void }) => {
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations } = useQuery({
    queryKey: ["admin_integrations"],
    queryFn: async () => {
      const { data, error } = await supabase.from("integrations").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const { data: config, refetch: refetchConfig } = useQuery({
    queryKey: ["platform_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: keyName },
      });
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  const getIntegration = (key: string) => integrations?.find((i: any) => i.key_name === key);
  const handleConfigSaved = () => {
    refetchConfig();
    qc.invalidateQueries({ queryKey: ["platform_config"] });
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-xl font-semibold">Integrations</h2>
        <p className="text-sm text-muted-foreground mt-1">Click any integration to expand configuration details, edit settings, and view the setup guide.</p>
      </div>
      <div className="space-y-3">
        <OpenAICard
          integration={getIntegration("OPENAI_API_KEY")}
          onTest={testIntegration}
          testing={testing}
        />
        <PostmarkCard
          integration={getIntegration("POSTMARK_API_TOKEN")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onConfigSaved={handleConfigSaved}
          onNavigateToEmail={onNavigateToEmail}
        />
        <DodoCard
          integration={getIntegration("DODO_PAYMENTS_API_KEY")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onConfigSaved={handleConfigSaved}
        />
      </div>
    </div>
  );
};

export default IntegrationsTab;

toolUseResult.content:
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import {
  CheckCircle2, XCircle, Loader2, ExternalLink, Mail, Brain, CreditCard,
  ChevronDown, Eye, EyeOff, Save, FlaskConical, RefreshCw,
} from "lucide-react";
import { useState } from "react";
import { logAuditAction } from "@/lib/auditLog";

// ─── Shared helpers ───────────────────────────────────────────────────────────

const StatusBadge = ({ status }: { status: string | null }) => {
  if (status === "success")
    return <Badge className="gap-1 bg-green-600 hover:bg-green-600 text-white text-xs shrink-0"><CheckCircle2 className="h-3 w-3" />Connected</Badge>;
  if (status === "failed")
    return <Badge variant="destructive" className="gap-1 text-xs shrink-0"><XCircle className="h-3 w-3" />Failed</Badge>;
  return <Badge variant="secondary" className="text-xs shrink-0">Not tested</Badge>;
};

const Step = ({ n, text }: { n: number; text: React.ReactNode }) => (
  <div className="flex gap-3">
    <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[11px] font-semibold text-primary mt-0.5">{n}</span>
    <p className="text-sm text-muted-foreground leading-relaxed">{text}</p>
  </div>
);

const SecretRow = ({ name, description }: { name: string; description?: string }) => (
  <div className="flex items-start justify-between gap-3 py-2">
    <div>
      <code className="text-xs bg-muted px-1.5 py-0.5 rounded font-mono">{name}</code>
      {description && <p className="text-xs text-muted-foreground mt-0.5">{description}</p>}
    </div>
    <Badge variant="outline" className="text-[10px] shrink-0">Env Secret</Badge>
  </div>
);

const InfoRow = ({ label, value }: { label: string; value: React.ReactNode }) => (
  <div className="flex items-center justify-between py-1.5 text-sm">
    <span className="text-muted-foreground">{label}</span>
    <span className="font-medium text-right">{value}</span>
  </div>
);

// ─── OpenAI Card ─────────────────────────────────────────────────────────────

const OpenAICard = ({ integration, onTest, testing }: any) => {
  const [open, setOpen] = useState(false);

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">

      {/* Header — always visible, click to expand */}
      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-violet-500/10 flex items-center justify-center shrink-0">
              <Brain className="h-5 w-5 text-violet-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">OpenAI</p>
              <p className="text-xs text-muted-foreground">GPT-4o · Resume ranking · JD analysis</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <StatusBadge status={integration?.last_test_status} />
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Secret info */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">API Credentials</p>
            <div className="rounded-lg border divide-y">
              <div className="px-3">
                <SecretRow name="OPENAI_API_KEY" description="Your OpenAI secret key — set in Supabase Edge Function Secrets" />
              </div>
            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Go to <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">platform.openai.com/api-keys</a> and create a new secret key</>} />
              <Step n={2} text={<>In your Supabase dashboard → <strong>Project Settings → Edge Functions → Secrets</strong></>} />
              <Step n={3} text={<>Click <strong>Add new secret</strong>, set name <code className="bg-background px-1 rounded text-xs">OPENAI_API_KEY</code> and paste your key</>} />
              <Step n={4} text="Click Test Connection below — status badge will turn green on success" />
            </div>
          </div>

          {/* Used by */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Used By</p>
            <div className="flex flex-wrap gap-1.5">
              {["rank-resumes", "analyze-jd", "evaluate-model"].map(fn => (
                <Badge key={fn} variant="outline" className="text-xs font-mono">{fn}</Badge>
              ))}
            </div>
          </div>

          <Separator />

          {/* Footer actions */}
          <div className="flex items-center justify-between">
            <p className="text-xs text-muted-foreground">
              {integration?.last_tested_at
                ? <>Last tested: {new Date(integration.last_tested_at).toLocaleString()}</>
                : "Never tested"}
            </p>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={() => onTest("OPENAI_API_KEY")} disabled={testing === "OPENAI_API_KEY"}>
                {testing === "OPENAI_API_KEY"
                  ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                  : <FlaskConical className="h-3.5 w-3.5 mr-1.5" />}
                Test Connection
              </Button>
              <Button variant="ghost" size="sm" asChild>
                <a href="https://platform.openai.com" target="_blank" rel="noopener noreferrer">
                  <ExternalLink className="h-3.5 w-3.5 mr-1.5" />Dashboard
                </a>
              </Button>
            </div>
          </div>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
};

// ─── Postmark Card ────────────────────────────────────────────────────────────

const PostmarkCard = ({ integration, config, onTest, testing, onConfigSaved }: any) => {
  const [open, setOpen] = useState(false);
  const [showToken, setShowToken] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    postmark_api_token: config?.postmark_api_token || "",
    email_from_address: config?.email_from_address || "noreply@rankora.co",
    email_from_name: config?.email_from_name || "Rankora",
    outbound_email_enabled: config?.outbound_email_enabled ?? false,
    email_notify_ranking_complete: config?.email_notify_ranking_complete ?? true,
    email_notify_resume_received: config?.email_notify_resume_received ?? true,
    inbound_email_domain: config?.inbound_email_domain || "inbound.rankora.co",
  });

  const save = async () => {
    if (!form.email_from_address.includes("@")) { toast.error("Enter a valid from address"); return; }
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({
          postmark_api_token: form.postmark_api_token || null,
          email_from_address: form.email_from_address,
          email_from_name: form.email_from_name,
          outbound_email_enabled: form.outbound_email_enabled,
          email_notify_ranking_complete: form.email_notify_ranking_complete,
          email_notify_resume_received: form.email_notify_resume_received,
          inbound_email_domain: form.inbound_email_domain,
        } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Postmark settings saved");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "postmark" });
      onConfigSaved?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const maskedToken = config?.postmark_api_token
    ? config.postmark_api_token.slice(0, 6) + "••••••••••••••••" + config.postmark_api_token.slice(-4)
    : null;

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">

      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-blue-500/10 flex items-center justify-center shrink-0">
              <Mail className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">Postmark</p>
              <p className="text-xs text-muted-foreground">Transactional email · Inbound parsing</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant={config?.outbound_email_enabled ? "default" : "secondary"} className="text-[10px] shrink-0">
              {config?.outbound_email_enabled ? "Outbound On" : "Outbound Off"}
            </Badge>
            <StatusBadge status={integration?.last_test_status} />
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Current config summary (read-only quick view) */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Current Config</p>
            <div className="rounded-lg border divide-y px-3">
              <InfoRow label="API Token" value={maskedToken ? <span className="font-mono text-xs">{maskedToken}</span> : <span className="text-muted-foreground italic text-xs">Not configured</span>} />
              <InfoRow label="From Address" value={config?.email_from_address || "noreply@rankora.co"} />
              <InfoRow label="From Name" value={config?.email_from_name || "Rankora"} />
              <InfoRow label="Inbound Domain" value={<span className="font-mono text-xs">{config?.inbound_email_domain || "inbound.rankora.co"}</span>} />
            </div>
          </div>

          {/* Edit form */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Edit Settings</p>
            <div className="space-y-4 rounded-lg border p-4">

              {/* API Token */}
              <div>
                <Label className="text-xs font-medium">Server API Token</Label>
                <p className="text-xs text-muted-foreground mb-1.5">Found in Postmark → Your Server → API Tokens</p>
                <div className="flex gap-2">
                  <Input
                    type={showToken ? "text" : "password"}
                    value={form.postmark_api_token}
                    onChange={(e) => setForm({ ...form, postmark_api_token: e.target.value })}
                    placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
                    className="font-mono text-sm flex-1"
                  />
                  <Button variant="outline" size="icon" onClick={() => setShowToken(!showToken)} title={showToken ? "Hide" : "Show"}>
                    {showToken ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </Button>
                </div>
              </div>

              {/* From address + name */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs font-medium">From Address</Label>
                  <Input
                    value={form.email_from_address}
                    onChange={(e) => setForm({ ...form, email_from_address: e.target.value })}
                    placeholder="noreply@rankora.co"
                    className="mt-1.5 text-sm"
                  />
                </div>
                <div>
                  <Label className="text-xs font-medium">From Name</Label>
                  <Input
                    value={form.email_from_name}
                    onChange={(e) => setForm({ ...form, email_from_name: e.target.value })}
                    placeholder="Rankora"
                    className="mt-1.5 text-sm"
                  />
                </div>
              </div>

              {/* Inbound domain */}
              <div>
                <Label className="text-xs font-medium">Inbound Email Domain</Label>
                <p className="text-xs text-muted-foreground mb-1.5">Domain that receives forwarded resumes via Postmark inbound</p>
                <Input
                  value={form.inbound_email_domain}
                  onChange={(e) => setForm({ ...form, inbound_email_domain: e.target.value })}
                  placeholder="inbound.rankora.co"
                  className="font-mono text-sm"
                />
              </div>

              <Separator />

              {/* Toggles */}
              <div className="space-y-3">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Notifications</p>
                {[
                  { key: "outbound_email_enabled", label: "Enable outbound emails", desc: "Send emails via Postmark (ranking complete, resume received)" },
                  { key: "email_notify_ranking_complete", label: "Ranking complete notification", desc: "Email candidate when ranking finishes" },
                  { key: "email_notify_resume_received", label: "Resume received notification", desc: "Email sender confirmation when resume is ingested" },
                ].map(({ key, label, desc }) => (
                  <div key={key} className="flex items-start justify-between gap-4">
                    <div>
                      <p className="text-sm font-medium">{label}</p>
                      <p className="text-xs text-muted-foreground">{desc}</p>
                    </div>
                    <Switch
                      checked={(form as any)[key]}
                      onCheckedChange={(c) => setForm({ ...form, [key]: c })}
                    />
                  </div>
                ))}
              </div>

              <Button size="sm" onClick={save} disabled={saving} className="w-full">
                {saving ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Save className="h-3.5 w-3.5 mr-1.5" />}
                Save Postmark Settings
              </Button>
            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Sign up at <a href="https://postmarkapp.com" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">postmarkapp.com</a> and create a Server</>} />
              <Step n={2} text={<>In your server, go to <strong>API Tokens</strong> tab and copy the <strong>Server API Token</strong></>} />
              <Step n={3} text="Paste the token in the API Token field above and click Save" />
              <Step n={4} text={<>Add your sender email (<code className="bg-background px-1 rounded text-xs">noreply@rankora.co</code>) in <strong>Sender Signatures</strong> and verify it</>} />
              <Step n={5} text={<>For inbound email: go to <strong>Inbound</strong> tab and set webhook URL to your Supabase email-ingest function URL</>} />
              <Step n={6} text={<>Add an MX record on your domain: <code className="bg-background px-1 rounded text-xs">inbound.rankora.co → inbound.postmarkapp.com</code> (priority 10)</>} />
              <Step n={7} text="Click Test Connection below to verify everything is working" />
            </div>
          </div>

          {/* Used by */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Used By</p>
            <div className="flex flex-wrap gap-1.5">
              {["send-email", "email-ingest", "ranking-complete"].map(fn => (
                <Badge key={fn} variant="outline" className="text-xs font-mono">{fn}</Badge>
              ))}
            </div>
          </div>

          <Separator />

          <div className="flex items-center justify-between">
            <p className="text-xs text-muted-foreground">
              {integration?.last_tested_at
                ? <>Last tested: {new Date(integration.last_tested_at).toLocaleString()}</>
                : "Never tested"}
            </p>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={() => onTest("POSTMARK_API_TOKEN")} disabled={testing === "POSTMARK_API_TOKEN"}>
                {testing === "POSTMARK_API_TOKEN"
                  ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                  : <FlaskConical className="h-3.5 w-3.5 mr-1.5" />}
                Test Connection
              </Button>
              <Button variant="ghost" size="sm" asChild>
                <a href="https://account.postmarkapp.com/servers" target="_blank" rel="noopener noreferrer">
                  <ExternalLink className="h-3.5 w-3.5 mr-1.5" />Dashboard
                </a>
              </Button>
            </div>
          </div>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
};

// ─── Dodo Payments Card ───────────────────────────────────────────────────────

const DodoCard = ({ integration, config, onTest, testing, onConfigSaved }: any) => {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [environment, setEnvironment] = useState<string>(config?.dodo_payments_environment || "test_mode");

  const envChanged = environment !== (config?.dodo_payments_environment || "test_mode");

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({ dodo_payments_environment: environment } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Dodo environment updated");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "dodo", environment });
      onConfigSaved?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">

      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-emerald-500/10 flex items-center justify-center shrink-0">
              <CreditCard className="h-5 w-5 text-emerald-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">Dodo Payments</p>
              <p className="text-xs text-muted-foreground">Credit packs · Subscriptions · Webhooks</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge
              variant={environment === "live_mode" ? "default" : "secondary"}
              className={`text-[10px] shrink-0 ${environment === "live_mode" ? "bg-emerald-600 hover:bg-emerald-600" : ""}`}
            >
              {environment === "live_mode" ? "Live" : "Test Mode"}
            </Badge>
            <StatusBadge status={integration?.last_test_status} />
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Environment selector */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Environment</p>
            <div className="rounded-lg border p-4 space-y-3">
              <div>
                <Label className="text-xs font-medium">Active Environment</Label>
                <p className="text-xs text-muted-foreground mb-2">Controls which Dodo API endpoint all functions call</p>
                <div className="flex gap-2">
                  <Select value={environment} onValueChange={setEnvironment}>
                    <SelectTrigger className="flex-1">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="test_mode">
                        <div className="flex items-center gap-2">
                          <FlaskConical className="h-3.5 w-3.5 text-muted-foreground" />
                          Test Mode — sandbox, no real charges
                        </div>
                      </SelectItem>
                      <SelectItem value="live_mode">
                        <div className="flex items-center gap-2">
                          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
                          Live Mode — production, real payments
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                  <Button size="sm" onClick={save} disabled={saving || !envChanged} variant={envChanged ? "default" : "outline"}>
                    {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
                  </Button>
                </div>
                {environment === "live_mode" && (
                  <p className="text-xs text-amber-600 bg-amber-500/10 rounded-md px-3 py-2 mt-2">
                    ⚠️ Live mode charges real money. Also update <code className="font-mono">DODO_PAYMENTS_ENVIRONMENT</code> in Supabase Secrets to match.
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Secrets reference */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">API Credentials</p>
            <p className="text-xs text-muted-foreground mb-2">These are stored as Supabase Edge Function Secrets (write-only, cannot be read from UI)</p>
            <div className="rounded-lg border divide-y px-3">
              <SecretRow name="DODO_PAYMENTS_API_KEY" description="Your Dodo API key from Dashboard → Developers → API Keys" />
              <SecretRow name="DODO_PAYMENTS_WEBHOOK_SECRET" description="Webhook signing secret from Dashboard → Developers → Webhooks" />
              <SecretRow name="DODO_PAYMENTS_ENVIRONMENT" description="Must match the environment selected above (test_mode or live_mode)" />
            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Sign up at <a href="https://dashboard.dodopayments.com" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">dashboard.dodopayments.com</a> and complete account setup</>} />
              <Step n={2} text={<>Go to <strong>Developers → API Keys</strong> and create a new API key. Copy it.</>} />
              <Step n={3} text={<>Go to <strong>Developers → Webhooks</strong>, create a webhook endpoint pointing to your Supabase <code className="bg-background px-1 rounded text-xs">dodo-webhook</code> function URL. Copy the signing secret.</>} />
              <Step n={4} text={<>In Supabase dashboard → <strong>Project Settings → Edge Functions → Secrets</strong>, add:<br />
                <span className="block mt-1 space-y-0.5 ml-1">
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">DODO_PAYMENTS_API_KEY</code> = your API key</span>
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">DODO_PAYMENTS_WEBHOOK_SECRET</code> = your webhook secret</span>
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">DODO_PAYMENTS_ENVIRONMENT</code> = <code className="bg-background px-1 rounded">test_mode</code></span>
                </span>
              </>} />
              <Step n={5} text="Select the environment above (Test Mode for now) and click the save icon" />
              <Step n={6} text={<>When going live: change <code className="bg-background px-1 rounded text-xs">DODO_PAYMENTS_ENVIRONMENT</code> secret to <code className="bg-background px-1 rounded text-xs">live_mode</code> AND update the selector above</>} />
              <Step n={7} text="Click Test Connection below to verify the API key works" />
            </div>
          </div>

          {/* Webhook info */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Webhook Endpoint</p>
            <div className="rounded-lg border bg-muted/40 p-3 flex items-center justify-between gap-3">
              <code className="text-xs font-mono break-all text-muted-foreground">
