// @ts-nocheck
// deno-lint-ignore-file no-explicit-any
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

const PAID_STATUSES = new Set(["paid", "completed", "succeeded", "success"]);
const FAILED_STATUSES = new Set(["failed", "cancelled", "canceled", "dismissed"]);

const toLocalStatus = (raw: string | null | undefined) => {
  const normalized = (raw || "").toLowerCase();
  if (PAID_STATUSES.has(normalized)) return "paid";
  if (FAILED_STATUSES.has(normalized)) return normalized === "canceled" ? "cancelled" : normalized;
  return null;
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY");
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";

    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SUPABASE_SERVICE_ROLE_KEY || !DODO_API_KEY) {
      return new Response(JSON.stringify({ error: "Server configuration error" }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: authHeader } },
    });

    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body = await req.json().catch(() => ({}));
    const paymentId = typeof body.payment_id === "string" ? body.payment_id : null;
    const localPaymentId = typeof body.local_payment_id === "string" ? body.local_payment_id : null;
    const checkoutSessionIdInput = typeof body.checkout_session_id === "string" ? body.checkout_session_id : null;

    if (!paymentId && !localPaymentId && !checkoutSessionIdInput) {
      return new Response(JSON.stringify({ error: "payment_id, local_payment_id, or checkout_session_id is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const baseUrl = DODO_ENV === "live_mode"
      ? "https://live.dodopayments.com"
      : "https://test.dodopayments.com";

    let dodoPayment: Record<string, any> | null = null;

    if (paymentId) {
      const paymentResponse = await fetch(`${baseUrl}/payments/${encodeURIComponent(paymentId)}`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${DODO_API_KEY}`,
          "Content-Type": "application/json",
        },
      });

      if (paymentResponse.ok) {
        dodoPayment = await paymentResponse.json();
      } else {
        const errorText = await paymentResponse.text();
        console.error("Failed to fetch Dodo payment:", paymentResponse.status, errorText);
      }
    }

    const resolvedPaymentId = paymentId || dodoPayment?.payment_id || dodoPayment?.id || null;
    const resolvedCheckoutSessionId = checkoutSessionIdInput || dodoPayment?.checkout_session_id || null;

    let paymentRow: Record<string, any> | null = null;

    if (localPaymentId) {
      const { data } = await supabase
        .from("payments")
        .select("*")
        .eq("id", localPaymentId)
        .eq("user_id", user.id)
        .maybeSingle();
      paymentRow = data || null;
    }

    if (!paymentRow && resolvedPaymentId) {
      const { data } = await supabase
        .from("payments")
        .select("*")
        .eq("dodo_payment_id", resolvedPaymentId)
        .eq("user_id", user.id)
        .maybeSingle();
      paymentRow = data || null;
    }

    if (!paymentRow && resolvedCheckoutSessionId) {
      const { data } = await supabase
        .from("payments")
        .select("*")
        .eq("dodo_checkout_session_id", resolvedCheckoutSessionId)
        .eq("user_id", user.id)
        .maybeSingle();
      paymentRow = data || null;
    }

    if (!paymentRow) {
      return new Response(JSON.stringify({ error: "Payment record not found for current user" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const dodoStatus = toLocalStatus(dodoPayment?.status);
    const updatePayload: Record<string, any> = {};

    if (resolvedPaymentId && paymentRow.dodo_payment_id !== resolvedPaymentId) {
      updatePayload.dodo_payment_id = resolvedPaymentId;
    }

    if (resolvedCheckoutSessionId && paymentRow.dodo_checkout_session_id !== resolvedCheckoutSessionId) {
      updatePayload.dodo_checkout_session_id = resolvedCheckoutSessionId;
    }

    if (Object.keys(updatePayload).length > 0) {
      await supabase.from("payments").update(updatePayload).eq("id", paymentRow.id);
    }

    let becamePaid = false;
    let finalStatus = paymentRow.status;

    if (dodoStatus === "paid") {
      const { data: paidUpdate } = await supabase
        .from("payments")
        .update({
          status: "paid",
          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
          ...(resolvedCheckoutSessionId ? { dodo_checkout_session_id: resolvedCheckoutSessionId } : {}),
        })
        .eq("id", paymentRow.id)
        .neq("status", "paid")
        .select("id")
        .maybeSingle();

      becamePaid = !!paidUpdate;
      finalStatus = "paid";

      if (becamePaid) {
        const { data: profile } = await supabase
          .from("profiles")
          .select("credits")
          .eq("user_id", paymentRow.user_id)
          .single();

        if (profile) {
          await supabase
            .from("profiles")
            .update({ credits: profile.credits + paymentRow.credits_purchased })
            .eq("user_id", paymentRow.user_id);
        }

        if (paymentRow.plan_id) {
          const { data: plan } = await supabase
            .from("plans")
            .select("name, billing_type")
            .eq("id", paymentRow.plan_id)
            .single();

          if (plan) {
            const endsAt = new Date();
            if (plan.billing_type === "yearly") {
              endsAt.setFullYear(endsAt.getFullYear() + 1);
            } else {
              endsAt.setMonth(endsAt.getMonth() + 1);
            }

            await supabase
              .from("profiles")
              .update({
                plan: plan.name,
                subscription_ends_at: endsAt.toISOString(),
                ...(dodoPayment?.subscription_id ? { dodo_subscription_id: dodoPayment.subscription_id } : {}),
              })
              .eq("user_id", paymentRow.user_id);
          }
        }
      }
    } else if (dodoStatus && dodoStatus !== paymentRow.status) {
      await supabase
        .from("payments")
        .update({ status: dodoStatus })
        .eq("id", paymentRow.id);
      finalStatus = dodoStatus;
    }

    return new Response(JSON.stringify({
      success: true,
      local_payment_id: paymentRow.id,
      dodo_payment_id: resolvedPaymentId,
      checkout_session_id: resolvedCheckoutSessionId,
      dodo_status: dodoPayment?.status || null,
      local_status: finalStatus,
      credits_added: becamePaid,
    }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    console.error("verify-dodo-payment error:", err);
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

