};

const PAID_STATUSES = new Set(["paid", "completed", "succeeded", "success"]);
const FAILED_STATUSES = new Set(["failed", "cancelled", "canceled", "dismissed"]);

const toLocalStatus = (raw: string | null | undefined) => {
  const normalized = (raw || "").toLowerCase();
  if (PAID_STATUSES.has(normalized)) return "paid";
  if (FAILED_STATUSES.has(normalized)) return normalized === "canceled" ? "cancelled" : normalized;
  return null;
};

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY");
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";

    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SUPABASE_SERVICE_ROLE_KEY || !DODO_API_KEY) {
      return new Response(JSON.stringify({ error: "Server configuration error" }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: authHeader } },
    });

    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body = await req.json().catch(() => ({}));
    const paymentId = typeof body.payment_id === "string" ? body.payment_id : null;
    const localPaymentId = typeof body.local_payment_id === "string" ? body.local_payment_id : null;
    const checkoutSessionIdInput = typeof body.checkout_session_id === "string" ? body.checkout_session_id : null;

    if (!paymentId && !localPaymentId && !checkoutSessionIdInput) {
      return new Response(JSON.stringify({ error: "payment_id, local_payment_id, or checkout_session_id is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const baseUrl = DODO_ENV === "live_mode"
      ? "https://live.dodopayments.com"
      : "https://test.dodopayments.com";

    // ── Step 1: find local payment record ────────────────────────────────────
    let paymentRow: Record<string, any> | null = null;

    if (localPaymentId) {
      const { data } = await supabase
        .from("payments")
        .select("*")
        .eq("id", localPaymentId)
        .eq("user_id", user.id)
        .maybeSingle();
      paymentRow = data || null;
    }

    if (!paymentRow && checkoutSessionIdInput) {
      const { data } = await supabase
        .from("payments")
        .select("*")
        .eq("dodo_checkout_session_id", checkoutSessionIdInput)
        .eq("user_id", user.id)
        .maybeSingle();
      paymentRow = data || null;
    }

    if (!paymentRow && paymentId) {
      const { data } = await supabase
        .from("payments")
        .select("*")
        .eq("dodo_payment_id", paymentId)
        .eq("user_id", user.id)
        .maybeSingle();
      paymentRow = data || null;
    }

    if (!paymentRow) {
      return new Response(JSON.stringify({ error: "Payment record not found for current user" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Step 2: if already paid in DB (webhook beat us here) — return now ───
    if (paymentRow.status === "paid") {
      return new Response(JSON.stringify({
        success: true,
        local_payment_id: paymentRow.id,
        dodo_payment_id: paymentRow.dodo_payment_id,
        checkout_session_id: paymentRow.dodo_checkout_session_id,
        dodo_status: "paid",
        local_status: "paid",
        credits_added: false,
      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    // ── Step 3: find the Dodo payment_id to query ────────────────────────────
    // For subscriptions Dodo doesn't include payment_id in the redirect URL,
    // so we need to search by checkout_session_id on Dodo's payments list API.
    let dodoPayment: Record<string, any> | null = null;

    const dodoPaymentIdToFetch = paymentId || paymentRow.dodo_payment_id || null;
    const sessionIdToSearch = checkoutSessionIdInput || paymentRow.dodo_checkout_session_id || null;

    // ── Step 3a: direct fetch by payment_id if we have it ────────────────────
    if (dodoPaymentIdToFetch) {
      const res = await fetch(`${baseUrl}/payments/${encodeURIComponent(dodoPaymentIdToFetch)}`, {
        headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
      });
      if (res.ok) {
        dodoPayment = await res.json();
        console.log("Fetched Dodo payment by ID:", dodoPayment?.payment_id, "status:", dodoPayment?.status);
      } else {
        console.error("Dodo payment fetch by ID failed:", res.status, await res.text());
      }
    }

    // ── Step 3b: search by checkout_session_id (subscription case) ───────────
    // Dodo payments list supports ?checkout_session_id= filter
    if (!dodoPayment && sessionIdToSearch) {
      const listRes = await fetch(`${baseUrl}/payments?checkout_session_id=${encodeURIComponent(sessionIdToSearch)}&page_size=5`, {
        headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
      });
      if (listRes.ok) {
        const listData = await listRes.json();
        // Response is either { items: [...] } or an array directly
        const items: any[] = Array.isArray(listData) ? listData : (listData.items || listData.data || []);
        if (items.length > 0) {
          dodoPayment = items[0];
          console.log("Found Dodo payment via session search:", dodoPayment?.payment_id, "status:", dodoPayment?.status);
        } else {
          console.log("No Dodo payment found for session yet, will retry");
        }
      } else {
        console.warn("Dodo payment list by session failed:", listRes.status, await listRes.text());
      }
    }

    // ── Step 3c: retry loop — subscriptions take a few seconds to register ───
    // If we still have no Dodo payment, retry up to 5 times with 2s gaps
    if (!dodoPayment && sessionIdToSearch) {
      for (let attempt = 1; attempt <= 5; attempt++) {
        await sleep(2000);
        console.log(`Retry ${attempt}/5 polling Dodo for session ${sessionIdToSearch}`);

        const listRes = await fetch(`${baseUrl}/payments?checkout_session_id=${encodeURIComponent(sessionIdToSearch)}&page_size=5`, {
          headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
        });
        if (listRes.ok) {
          const listData = await listRes.json();
          const items: any[] = Array.isArray(listData) ? listData : (listData.items || listData.data || []);
          if (items.length > 0) {
            dodoPayment = items[0];
            console.log("Found payment on retry", attempt, ":", dodoPayment?.payment_id, dodoPayment?.status);
            break;
          }
        }

        // Also check local DB — webhook may have arrived during our sleep
        const { data: refreshed } = await supabase
          .from("payments")
          .select("*")
          .eq("id", paymentRow.id)
          .single();
        if (refreshed?.status === "paid") {
          console.log("Webhook marked payment paid during retry loop");
          return new Response(JSON.stringify({
            success: true,
            local_payment_id: refreshed.id,
            dodo_payment_id: refreshed.dodo_payment_id,
            checkout_session_id: refreshed.dodo_checkout_session_id,
            dodo_status: "paid",
