        if (refreshed?.status === "paid") {
          console.log("Webhook marked payment paid during retry loop");
          return new Response(JSON.stringify({
            success: true,
            local_payment_id: refreshed.id,
            dodo_payment_id: refreshed.dodo_payment_id,
            checkout_session_id: refreshed.dodo_checkout_session_id,
            dodo_status: "paid",
            local_status: "paid",
            credits_added: false,
          }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }
      }
    }

    // ── Step 4: if we still have no Dodo payment data, return pending ─────────
    if (!dodoPayment) {
      console.warn("Could not fetch Dodo payment after retries — returning pending");
      return new Response(JSON.stringify({
        success: true,
        local_payment_id: paymentRow.id,
        dodo_status: null,
        local_status: paymentRow.status, // 'created' — frontend will keep polling
        credits_added: false,
      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    // ── Step 5: store dodo_payment_id if we just discovered it ───────────────
    const resolvedPaymentId = dodoPayment.payment_id || dodoPayment.id || dodoPaymentIdToFetch || null;
    const resolvedSessionId = dodoPayment.checkout_session_id || sessionIdToSearch || null;
    const resolvedSubscriptionId = dodoPayment.subscription_id || null;

    const updatePayload: Record<string, any> = {};
    if (resolvedPaymentId && paymentRow.dodo_payment_id !== resolvedPaymentId) updatePayload.dodo_payment_id = resolvedPaymentId;
    if (resolvedSessionId && paymentRow.dodo_checkout_session_id !== resolvedSessionId) updatePayload.dodo_checkout_session_id = resolvedSessionId;
    if (Object.keys(updatePayload).length > 0) {
      await supabase.from("payments").update(updatePayload).eq("id", paymentRow.id);
    }

    // ── Step 6: process paid status ──────────────────────────────────────────
    const dodoStatus = toLocalStatus(dodoPayment.status);
    let becamePaid = false;
    let finalStatus = paymentRow.status;

    if (dodoStatus === "paid") {
      // Atomic update: only fires if not already paid (idempotent)
      const { data: paidUpdate } = await supabase
        .from("payments")
        .update({
          status: "paid",
          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
          ...(resolvedSessionId ? { dodo_checkout_session_id: resolvedSessionId } : {}),
        })
        .eq("id", paymentRow.id)
        .neq("status", "paid")
        .select("id")
        .maybeSingle();

      becamePaid = !!paidUpdate;
      finalStatus = "paid";

      if (becamePaid) {
        // Add credits
        const { data: profile } = await supabase
          .from("profiles")
